import React from 'react';
import './ThankPage.scss';

import CartServices from 'path/to/CartServices';
import DoctorServices from 'path/to/DoctorServices';

const ThankPage = () => {
    const doctorsInCart = CartServices.getDoctorsInCart();

    const clearDoctorsFromCart = async () => {
        try {
            for (const doctor of doctorsInCart) {
                await DoctorServices.delete(doctor.id);
            }
            console.log('All doctors deleted successfully');
        } catch (error) {
            console.error('Failed to delete doctors:', error);
        }
    };

    useEffect(() => {
        clearDoctorsFromCart();
    }, []);

    return (
        <div className="thank-page">
            <h1>Thank You for Your Order!</h1>
            <p>Your order has been successfully submitted. We will contact you soon with the details.</p>
            <a href="/" className="home-link">Return to Home</a>
        </div>
    );
};

export default ThankPage;
